olid #e5e7eb;border-radius:12px;background:white;padding:6px;box-shadow:0 16px 40px rgba(15,23,42,.14)}.dark .vx-export-menu{background:#111827;border-color:#374151}.vx-export-menu button{display:flex;width:100%;padding:9px 10px;border-radius:8px;font-size:.8rem;font-weight:650}.vx-export-menu button:hover{background:#f8fafc}.dark .vx-export-menu button:hover{background:#1f2937}@media(max-width:1250px){.vx-quick-reports{grid-template-columns:repeat(4,1fr)}}@media(max-width:1100px){.vx-builder-fields{display:grid;grid-template-columns:repeat(2,1fr);gap:0 12px}}@media(max-width:1000px){.vx-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.vx-report-grid{grid-template-columns:1fr}.vx-filter-row{grid-template-columns:1fr 1fr}.vx-report-head{align-items:flex-start;flex-direction:column}.vx-report-actions{justify-content:flex-start}}@media(max-width:640px){.vx-builder-fields{grid-template-columns:1fr}.vx-quick-reports{grid-template-columns:1fr 1fr}.vx-filter-row{grid-template-columns:1fr}.vx-kpis{grid-template-columns:1fr 1fr}.vx-kpi{padding:13px}.vx-kpi-value{font-size:1.15rem}.vx-report-table{overflow:auto}.vx-table{min-width:760px}.vx-sheet-toolbar{flex-wrap:wrap;align-items:stretch}.vx-tabs{width:100%;flex:1 1 100%}.vx-sheet-actions{width:100%;flex:1 1 100%}.vx-sheet-actions select{flex:1;min-width:0;width:100%}}
.vx-two-columns{grid-template-columns:repeat(2,minmax(0,1fr))}.vx-kpi-value{overflow-wrap:anywhere}.vx-kpi{cursor:pointer;text-align:left}.vx-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.vx-flow-number{font-size:1.4rem;font-weight:800;margin:6px 0}.vx-aging{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.vx-thumb{height:40px;width:40px;object-fit:contain;border-radius:8px;background:#f8fafc;flex:none}@media(max-width:640px){.vx-flow{grid-template-columns:repeat(2,minmax(0,1fr))}.vx-kpi{flex-direction:column}.vx-aging{grid-template-columns:1fr}.vx-report-grid{grid-template-columns:1fr}}
